def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a dictionary to store grid values based on coordinates
    grid = {(x, y): v for x, y, v in grid_values if x != 0 or y != 0 or v != 0}

    # Initialize a 4D DP table with -inf
    dp = [[[[float('-inf')] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)] for _ in range(N + 1)]
    dp[0][0][0][0] = 0

    # Iterate over all possible positions for the two paths
    for i in range(N):
        for j in range(N):
            for k in range(N):
                for l in range(N):
                    # Calculate the current value based on grid values
                    current_value = grid.get((i, j), 0) + (grid.get((k, l), 0) if (i, j) != (k, l) else 0)

                    # Update the DP table considering moves from the previous positions
                    if i > 0 and k > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i-1][j][k-1][l] + current_value)
                    if i > 0 and l > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i-1][j][k][l-1] + current_value)
