def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    from collections import defaultdict

    # Count potential separations for horizontal aisles
    horizontal_separations = defaultdict(int)
    for row in range(1, M):
        for (x1, y1, x2, y2) in chatting_pairs:
            if x1 != x2 and (x1 == row or x2 == row) and y1 != y2:
                horizontal_separations[row] += 1

    # Count potential separations for vertical aisles
    vertical_separations = defaultdict(int)
    for col in range(1, N):
        for (x1, y1, x2, y2) in chatting_pairs:
            if y1 != y2 and (y1 == col or y2 == col) and x1 != x2:
                vertical_separations[col] += 1

    # Find the best K horizontal separations
    best_horizontal_positions = sorted(horizontal_separations.keys(), key=lambda x: -horizontal_separations[x])[:K]
    best_horizontal_positions.sort()

    # Find the best L vertical separations
    best_vertical_positions = sorted(vertical_separations.keys(), key=lambda x: -vertical_separations[x])[:L]
    best_vertical_positions.sort()

    return ' '.join(map(str, best_horizontal_positions)), ' '.join(map(str, best_vertical_positions))

