def count_passing_ways(n: int, m: int) -> int:
    if n < 2:
        return 0 if m > 0 else 1
    if m == 0:
        return 1

    # dp[i][j] will represent the number of ways to reach student j after i passes
    dp = [[0] * n for _ in range(m + 1)]
