def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort applicants by test score descending, then by registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Calculate the interview score cutoff based on 150% of the planned number of recruits, rounded down
    interview_cutoff_index = (m * 3) // 2

    # Determine the interview score cutoff
    if interview_cutoff_index < n:
        interview_score_cutoff = sorted_applicants[interview_cutoff_index - 1][1]
    else:
        interview_score_cutoff = sorted_applicants[-1][1]

    # Find the actual cutoff score in case there are ties
    for i in range(interview_cutoff_index - 1, -1, -1):
        if sorted_applicants[i][1] < interview_score_cutoff:
            break
    else:
        i = -1

    interview_score_cutoff = sorted_applicants[i + 1][1]

    # Select qualified applicants
    qualified_applicants = [applicant for applicant in sorted_applicants if applicant[1] >= interview_score_cutoff]

    return interview_score_cutoff, qualified_applicants

