def count_partitions(n: int, k: int, x: int) -> int:
    # If n is less than k times x, it's not possible to partition n into k parts each at least x
    if n < k * x:
        return 0
    # If k is 1, there is only one way to partition n if n is at least x
    if k == 1:
        return 1 if n >= x else 0
    # Use dynamic programming to count the number of partitions
    # dp[i][j] will store the number of ways to partition i into j parts each at least x
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(x, n + 1):
        dp[i][1] = 1
    for j in range(2, k + 1):
        for i in range(x * j, n + 1):
            dp[i][j] = dp[i - x][j - 1] + dp[i - 1][j] - dp[i - x - 1][j - 1] if i >= x + 1 else dp[i - x][j - 1]
    return dp[n][k]

