def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Convert the number to a string to manipulate individual digits
    num_str = str(n)

    # Create a mapping of transformation rules
    transform_map = defaultdict(list)
    for x, y in rules:
        transform_map[str(x)].append(str(y))

    # Initialize BFS
    queue = deque([num_str])
    visited = set([num_str])

    while queue:
        current = queue.popleft()

        # Generate all possible transformations of the current number
        for i in range(len(current)):
            if current[i] in transform_map:
                for transformed_digit in transform_map[current[i]]:
                    new_number = current[:i] + transformed_digit + current[i+1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    # Return the count of unique numbers generated
    return len(visited)

