def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, stmts in statements.items():
        for stmt in stmts:
            if any(day in stmt for day in days_of_week):
                continue
            elif scenario in stmt:
                if participant in liar_count and "not guilty" in stmt:
                    continue
                elif participant not in liar_count and "guilty" in stmt:
                    continue
