def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the maximum value at each time
    dp = [0] * (T + 1)

    # Iterate over each herb
    for time, value in herbs:
        # Traverse the dp array backwards to avoid overwriting
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    # The maximum value within the time limit is the last element in dp
    return dp[T]

