def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0

    # Initialize the DP arrays
    left_dps = [1] * n
    right_dps = [1] * n

    # Fill the left_dps array
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i]:
                left_dps[i] = max(left_dps[i], left_dps[j] + 1)

    # Fill the right_dps array
    for i in range(n-1, -1, -1):
        for j in range(i+1, n):
            if heights[j] < heights[i]:
                right_dps[i] = max(right_dps[i], right_dps[j] + 1)

    # Calculate the minimum students to leave
    min_students_to_leave = n
    for i in range(n):
        # Subtract 1 because the peak student is counted twice
        total_students_in_choir = left_dps[i] + right_dps[i] - 1
        students_to_leave = n - total_students_in_choir
        min_students_to_leave = min(min_students_to_leave, students_to_leave)

    return min_students_to_leave

